{
  "name": "Smart Park AI",
  "description": "Never lose your car again. Records your parking location and uses Gemini AI to analyze your parking spot photo for floor and spot numbers.",
  "requestFramePermissions": [
    "camera",
    "geolocation"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface GeoLocation {
  latitude: number;
  longitude: number;
  accuracy: number;
}

export interface ParkingLocation {
  id: string;
  timestamp: number;
  coords: GeoLocation;
  photoBase64?: string;
  notes?: string;
  floor?: string;
  spotNumber?: string;
  aiAnalysis?: string;
}

export enum AppState {
  IDLE = 'IDLE',
  LOCATING = 'LOCATING',
  ANALYZING = 'ANALYZING',
  PARKED = 'PARKED',
  ERROR = 'ERROR'
}

export interface AiAnalysisResult {
  floor: string | null;
  spotNumber: string | null;
  description: string | null;
}

import { GoogleGenAI, Type } from "@google/genai";
import { AiAnalysisResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeParkingPhoto = async (base64Image: string): Promise<AiAnalysisResult> => {
  try {
    // We strip the data url prefix if present to get raw base64
    const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Data
            }
          },
          {
            text: "Analyze this parking photo. Identify the floor level (e.g., B1, Level 2), the parking spot number, and a brief visual description of the surroundings (landmarks, colors, pillars) to help find the car later."
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            floor: { type: Type.STRING, description: "The floor level if visible, otherwise null" },
            spotNumber: { type: Type.STRING, description: "The parking spot number if visible, otherwise null" },
            description: { type: Type.STRING, description: "A short, helpful visual description of where the car is parked" }
          }
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini");
    }

    return JSON.parse(text) as AiAnalysisResult;
  } catch (error) {
    console.error("Gemini analysis failed:", error);
    // Return empty result on failure to not block the user flow
    return {
      floor: null,
      spotNumber: null,
      description: null
    };
  }
};

import { ParkingLocation } from "../types";

const STORAGE_KEY = 'smart_park_data';

export const saveParkingRecord = (record: ParkingLocation): void => {
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(record));
  } catch (e) {
    console.error("Failed to save to local storage", e);
  }
};

export const getParkingRecord = (): ParkingLocation | null => {
  try {
    const data = localStorage.getItem(STORAGE_KEY);
    return data ? JSON.parse(data) : null;
  } catch (e) {
    console.error("Failed to read from local storage", e);
    return null;
  }
};

export const clearParkingRecord = (): void => {
  try {
    localStorage.removeItem(STORAGE_KEY);
  } catch (e) {
    console.error("Failed to clear local storage", e);
  }
};

import React from 'react';

interface ButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  variant?: 'primary' | 'secondary' | 'danger' | 'ghost';
  isLoading?: boolean;
  icon?: React.ReactNode;
}

export const Button: React.FC<ButtonProps> = ({ 
  children, 
  variant = 'primary', 
  isLoading, 
  icon,
  className = '',
  ...props 
}) => {
  const baseStyles = "relative flex items-center justify-center px-6 py-3 rounded-xl font-semibold transition-all duration-200 active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed";

  const variants = {
    primary: "bg-indigo-600 text-white hover:bg-indigo-700 shadow-lg shadow-indigo-500/30",
    secondary: "bg-white text-gray-800 border border-gray-200 hover:bg-gray-50",
    danger: "bg-red-50 text-red-600 hover:bg-red-100 border border-red-100",
    ghost: "bg-transparent text-gray-600 hover:bg-gray-100"
  };

  return (
    <button 
      className={`${baseStyles} ${variants[variant]} ${className}`}
      disabled={isLoading || props.disabled}
      {...props}
    >
      {isLoading ? (
        <svg className="animate-spin -ml-1 mr-2 h-5 w-5" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
      ) : icon ? (
        <span className="mr-2">{icon}</span>
      ) : null}
      {children}
    </button>
  );
};

import React from 'react';

interface InfoCardProps {
