import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Camera, Clock, Navigation, Trash2, Save, Car, Loader2, Map as MapIcon, Edit2 } from 'lucide-react';
import { GeoLocation, ParkingLocation, AppState } from './types';
import { analyzeParkingPhoto } from './services/geminiService';
import { saveParkingRecord, getParkingRecord, clearParkingRecord } from './utils/storage';
import { Button } from './components/Button';
import { InfoCard } from './components/InfoCard';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [parkingData, setParkingData] = useState<ParkingLocation | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [elapsedTime, setElapsedTime] = useState<string>("0m");
  const [editMode, setEditMode] = useState(false);

  // Edit form state
  const [manualFloor, setManualFloor] = useState("");
  const [manualSpot, setManualSpot] = useState("");
  const [manualNotes, setManualNotes] = useState("");

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Load saved data on mount
  useEffect(() => {
    const saved = getParkingRecord();
    if (saved) {
      setParkingData(saved);
      setAppState(AppState.PARKED);
    }
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: number;
    if (appState === AppState.PARKED && parkingData) {
      const updateTimer = () => {
        const now = Date.now();
        const diff = now - parkingData.timestamp;
        const minutes = Math.floor(diff / 60000);
        const hours = Math.floor(minutes / 60);

        if (hours > 0) {
          setElapsedTime(`${hours}h ${minutes % 60}m`);
        } else {
          setElapsedTime(`${minutes}m`);
        }
      };

      updateTimer();
      interval = window.setInterval(updateTimer, 60000);
    }
    return () => clearInterval(interval);
  }, [appState, parkingData]);

  const handleStartParking = async () => {
    setErrorMsg(null);
    setAppState(AppState.LOCATING);

    if (!navigator.geolocation) {
      setErrorMsg("Geolocation is not supported by your browser.");
      setAppState(AppState.IDLE);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const coords: GeoLocation = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        };

        // Temporarily store coords and ask for photo
        setParkingData({
          id: Date.now().toString(),
          timestamp: Date.now(),
          coords: coords
        } as ParkingLocation);

        // Trigger file input immediately after location found for smoother UX
        if (fileInputRef.current) {
          fileInputRef.current.click();
        }
      },
      (error) => {
        setErrorMsg(`Unable to retrieve location: ${error.message}`);
        setAppState(AppState.ERROR);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !parkingData) return;

    // Convert to base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      setTempPhoto(base64String);
      setAppState(AppState.ANALYZING);

      // Analyze with Gemini
      const analysis = await analyzeParkingPhoto(base64String);

      const newRecord: ParkingLocation = {
        ...parkingData,
        photoBase64: base64String,
        floor: analysis.floor || undefined,
        spotNumber: analysis.spotNumber || undefined,
        aiAnalysis: analysis.description || undefined,
        notes: analysis.description || undefined
      };

      setParkingData(newRecord);
      setManualFloor(newRecord.floor || "");
      setManualSpot(newRecord.spotNumber || "");
      setManualNotes(newRecord.notes || "");

      saveParkingRecord(newRecord);
      setAppState(AppState.PARKED);
    };
    reader.readAsDataURL(file);
  };

  const handleSkipPhoto = () => {
    if (parkingData) {
      saveParkingRecord(parkingData);
      setAppState(AppState.PARKED);
    }
  };

  const handleClearParking = () => {
    if (window.confirm("Are you sure you want to clear your parking location?")) {
      clearParkingRecord();
      setParkingData(null);
      setTempPhoto(null);
      setAppState(AppState.IDLE);
      setEditMode(false);
    }
  };

  const handleUpdateRecord = () => {
    if (!parkingData) return;
    const updated: ParkingLocation = {
      ...parkingData,
      floor: manualFloor,
      spotNumber: manualSpot,
      notes: manualNotes
    };
    setParkingData(updated);
    saveParkingRecord(updated);
    setEditMode(false);
  };

  const openMap = () => {
    if (!parkingData) return;
    const { latitude, longitude } = parkingData.coords;
    // Use universal Google Maps URL
    window.open(`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`, '_blank');
  };

  // ---------------- Render Views ----------------

  const renderIdle = () => (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fade-in">
      <div className="relative">
        <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 rounded-full animate-pulse"></div>
        <div className="bg-white p-6 rounded-3xl shadow-xl relative z-10">
          <Car className="w-16 h-16 text-indigo-600" />
        </div>
      </div>

      <div className="space-y-2">
        <h2 className="text-3xl font-bold text-gray-800">Ready to Park?</h2>
        <p className="text-gray-500 max-w-xs mx-auto">We'll save your location and use AI to remember your spot number.</p>
      </div>

      <div className="w-full max-w-xs">
        <Button 
          onClick={handleStartParking} 
          className="w-full h-16 text-lg shadow-indigo-500/40 hover:shadow-indigo-500/50"
          icon={<MapPin className="w-6 h-6" />}
        >
          Record Parking Location
        </Button>
      </div>

      {/* Hidden file input for the flow */}
      <input 
        type="file" 
        accept="image/*" 
        capture="environment"
        ref={fileInputRef}
        onChange={handlePhotoUpload}
        className="hidden"
      />
    </div>
  );

  const renderLocating = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
      <Loader2 className="w-12 h-12 text-indigo-600 animate-spin" />
      <p className="text-lg font-medium text-gray-700">Acquiring GPS Signal...</p>
      <p className="text-sm text-gray-400">Please stand still for better accuracy</p>
    </div>
  );

  const renderAnalyzing = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-6">
      <div className="relative w-full max-w-sm aspect-video rounded-2xl overflow-hidden shadow-lg border-2 border-indigo-100">
        {tempPhoto && (
          <img src={tempPhoto} alt="Parking" className="w-full h-full object-cover opacity-50" />
        )}
        <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[2px]">
          <div className="bg-white/90 p-4 rounded-full shadow-lg">
             <div className="animate-spin text-indigo-600">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                </svg>
             </div>
          </div>
        </div>
      </div>
      <div className="text-center">
        <h3 className="text-xl font-bold text-gray-800 mb-2">Analyzing Image...</h3>
        <p className="text-gray-500 text-sm max-w-xs">Gemini AI is reading floor and spot numbers from your photo.</p>
      </div>
    </div>
  );

  const renderParked = () => {
    if (!parkingData) return null;

    if (editMode) {
      return (
        <div className="space-y-6 animate-fade-in">
           <div className="flex items-center justify-between mb-4">
             <h2 className="text-xl font-bold text-gray-800">Edit Details</h2>
             <button onClick={() => setEditMode(false)} className="text-gray-500 hover:text-gray-700">Cancel</button>
           </div>

           <div className="space-y-4">
             <div>
               <label className="block text-sm font-medium text-gray-700 mb-1">Floor Level</label>
               <input 
                  type="text" 
                  value={manualFloor} 
                  onChange={(e) => setManualFloor(e.target.value)}
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                  placeholder="e.g. B2, Lvl 4"
               />
             </div>
             <div>
               <label className="block text-sm font-medium text-gray-700 mb-1">Spot Number</label>
               <input 
                  type="text" 
                  value={manualSpot} 
                  onChange={(e) => setManualSpot(e.target.value)}
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                  placeholder="e.g. 402, A-12"
               />
             </div>
             <div>
               <label className="block text-sm font-medium text-gray-700 mb-1">Notes / Description</label>
               <textarea 
                  value={manualNotes} 
                  onChange={(e) => setManualNotes(e.target.value)}
                  className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all h-24 resize-none"
                  placeholder="Near the elevator..."
               />
             </div>
             <Button onClick={handleUpdateRecord} className="w-full" icon={<Save className="w-4 h-4" />}>
               Save Changes
             </Button>
           </div>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-fade-in pb-24">
        {/* Header Status */}
        <div className="bg-indigo-600 rounded-3xl p-6 text-white shadow-xl shadow-indigo-200">
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <span className="flex h-3 w-3 relative">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span>
              </span>
              <span className="font-semibold tracking-wide text-sm opacity-90">CURRENTLY PARKED</span>
            </div>
            <div className="flex items-center space-x-1 bg-white/20 px-3 py-1 rounded-full text-xs font-medium">
              <Clock className="w-3 h-3" />
              <span>{elapsedTime}</span>
            </div>
          </div>

          <div className="flex justify-between items-end">
             <div>
               <p className="text-indigo-200 text-sm mb-1">Floor</p>
               <p className="text-3xl font-bold">{parkingData.floor || "--"}</p>
             </div>
             <div className="text-right">
               <p className="text-indigo-200 text-sm mb-1">Spot</p>
               <p className="text-3xl font-bold">{parkingData.spotNumber || "--"}</p>
             </div>
          </div>
        </div>

        {/* Photo Section */}
        {parkingData.photoBase64 ? (
          <div className="relative rounded-2xl overflow-hidden shadow-md border border-gray-100 group">
             <img src={parkingData.photoBase64} alt="Parking Spot" className="w-full h-48 object-cover" />
             <div className="absolute inset-0 bg-gradient-to-t from-black/60 to-transparent opacity-0 group-hover:opacity-100 transition-opacity flex items-end justify-center p-4">
               <span className="text-white text-xs font-medium">Recorded Photo</span>
             </div>
          </div>
        ) : (
          <div className="bg-gray-100 rounded-2xl h-24 flex items-center justify-center text-gray-400 text-sm">
            No photo recorded
          </div>
        )}

        {/* Location & Actions */}
        <div className="grid grid-cols-2 gap-3">
          <Button variant="secondary" onClick={openMap} className="flex-col py-4 h-auto space-y-2">
             <Navigation className="w-6 h-6 text-blue-500" />
             <span className="text-xs font-medium">Navigate</span>
          </Button>
          <Button variant="secondary" onClick={() => setEditMode(true)} className="flex-col py-4 h-auto space-y-2">
             <Edit2 className="w-6 h-6 text-orange-500" />
             <span className="text-xs font-medium">Edit Details</span>
          </Button>
        </div>

        {/* Notes Card */}
        {parkingData.notes && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
             <h4 className="text-sm font-semibold text-gray-900 mb-2 flex items-center">
               <MapIcon className="w-4 h-4 mr-2 text-gray-400" />
               Location Notes
             </h4>
             <p className="text-gray-600 text-sm leading-relaxed">{parkingData.notes}</p>
          </div>
        )}

        {/* Bottom Action */}
        <div className="fixed bottom-6 left-6 right-6">
           <Button variant="danger" onClick={handleClearParking} className="w-full shadow-lg shadow-red-200" icon={<Trash2 className="w-5 h-5" />}>
             End Parking & Clear
           </Button>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans selection:bg-indigo-100">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl relative overflow-hidden">
        {/* Background Decorations */}
        <div className="absolute top-0 left-0 right-0 h-64 bg-gradient-to-b from-indigo-50/50 to-transparent pointer-events-none"></div>

        {/* Header */}
        <header className="px-6 pt-8 pb-2 relative z-10 flex items-center justify-between">
           <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
             Smart Park AI
           </h1>
           {/* Debug info or simple status indicator could go here */}
        </header>

        {/* Main Content */}
        <main className="px-6 py-4 relative z-10">
          {errorMsg && (
            <div className="mb-6 bg-red-50 border border-red-100 text-red-600 px-4 py-3 rounded-xl text-sm flex items-start">
              <span className="mr-2">⚠️</span>
              {errorMsg}
            </div>
          )}

          {appState === AppState.IDLE && renderIdle()}
          {appState === AppState.LOCATING && renderLocating()}
          {appState === AppState.ANALYZING && renderAnalyzing()}
          {appState === AppState.PARKED && renderParked()}
          {appState === AppState.ERROR && (
             <div className="text-center py-10">
               <p className="text-gray-500 mb-4">Something went wrong.</p>
               <Button onClick={() => setAppState(AppState.IDLE)}>Try Again</Button>
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

export interface GeoLocation {
  latitude: number;
  longitude: number;
  accuracy: number;
}

export interface ParkingLocation {
  id: string;
  timestamp: number;
  coords: GeoLocation;
  photoBase64?: string;
  notes?: string;
  floor?: string;
  spotNumber?: string;
  aiAnalysis?: string;
  durationMinutes?: number;
}

export enum AppState {
  IDLE = 'IDLE',
  LOCATING = 'LOCATING',
  ANALYZING = 'ANALYZING',
  PARKED = 'PARKED',
  ERROR = 'ERROR'
}

export interface AiAnalysisResult {
  floor: string | null;
  spotNumber: string | null;
  description: string | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Camera, Clock, Navigation, Trash2, Save, Car, Loader2, Map as MapIcon, Edit2, Bell, AlertTriangle, Plus } from 'lucide-react';
import { GeoLocation, ParkingLocation, AppState } from './types';
import { analyzeParkingPhoto } from './services/geminiService';
import { saveParkingRecord, getParkingRecord, clearParkingRecord } from './utils/storage';
import { Button } from './components/Button';
import { InfoCard } from './components/InfoCard';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [parkingData, setParkingData] = useState<ParkingLocation | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Timer state
  const [elapsedTime, setElapsedTime] = useState<string>("0m");
  const [remainingTime, setRemainingTime] = useState<string | null>(null);
  const [isExpired, setIsExpired] = useState(false);

  // UI state
  const [editMode, setEditMode] = useState(false);
  const [showTimerSetup, setShowTimerSetup] = useState(false);

  // Edit form state
  const [manualFloor, setManualFloor] = useState("");
  const [manualSpot, setManualSpot] = useState("");
  const [manualNotes, setManualNotes] = useState("");
  const [timerDuration, setTimerDuration] = useState<number | null>(null); // minutes

  const fileInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);
  const notificationSentRef = useRef(false);

  // Load saved data on mount
  useEffect(() => {
    const saved = getParkingRecord();
    if (saved) {
      setParkingData(saved);
      setTimerDuration(saved.durationMinutes || null);
      setAppState(AppState.PARKED);
    }

    // Request notification permission early
    if ('Notification' in window) {
      Notification.requestPermission();
    }
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: number;
    if (appState === AppState.PARKED && parkingData) {
      const updateTimer = () => {
        const now = Date.now();
        const diff = now - parkingData.timestamp;

        // Update Elapsed
        const eMinutes = Math.floor(diff / 60000);
        const eHours = Math.floor(eMinutes / 60);
        if (eHours > 0) {
          setElapsedTime(`${eHours}h ${eMinutes % 60}m`);
        } else {
          setElapsedTime(`${eMinutes}m`);
        }

        // Update Remaining if timer set
        if (parkingData.durationMinutes) {
          const endTime = parkingData.timestamp + (parkingData.durationMinutes * 60000);
          const remainingMs = endTime - now;

          if (remainingMs <= 0) {
            setRemainingTime("Expired");
            setIsExpired(true);
            if (!notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
              new Notification("Parking Meter Expired", { body: "Your parking session has ended." });
              notificationSentRef.current = true;
            }
          } else {
            setIsExpired(false);
            const rMinutes = Math.floor(remainingMs / 60000);
            const rHours = Math.floor(rMinutes / 60);
            const displayMin = rMinutes % 60;

            setRemainingTime(`${rHours}:${displayMin.toString().padStart(2, '0')}`);

            // Notify if 15 mins left
            if (rMinutes <= 15 && !notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
               new Notification("Parking Expiring Soon", { body: `You have ${rMinutes} minutes left.` });
               notificationSentRef.current = true;
            }
          }
        } else {
          setRemainingTime(null);
          setIsExpired(false);
        }
      };

      updateTimer();
      interval = window.setInterval(updateTimer, 30000); // Update every 30s
    }
    return () => clearInterval(interval);
  }, [appState, parkingData]);

  const handleStartParking = async () => {
    setErrorMsg(null);
    setAppState(AppState.LOCATING);

    if (!navigator.geolocation) {
      setErrorMsg("Geolocation is not supported by your browser.");
      setAppState(AppState.IDLE);
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        const coords: GeoLocation = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        };

        // Temporarily store coords and ask for photo
        setParkingData({
          id: Date.now().toString(),
          timestamp: Date.now(),
          coords: coords
        } as ParkingLocation);

        // Trigger file input immediately after location found for smoother UX
        if (fileInputRef.current) {
          fileInputRef.current.click();
        }
      },
      (error) => {
        setErrorMsg(`Unable to retrieve location: ${error.message}`);
        setAppState(AppState.ERROR);
      },
      { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 }
    );
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !parkingData) return;

    processAndSavePhoto(file);
  };

  const processAndSavePhoto = (file: File) => {
    // Convert to base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      setTempPhoto(base64String);
      setAppState(AppState.ANALYZING);

      // Analyze with Gemini
      const analysis = await analyzeParkingPhoto(base64String);

      const newRecord: ParkingLocation = {
        ...parkingData!,
        photoBase64: base64String,
        floor: analysis.floor || undefined,
        spotNumber: analysis.spotNumber || undefined,
        aiAnalysis: analysis.description || undefined,
        notes: analysis.description || undefined
      };

      setParkingData(newRecord);
      setManualFloor(newRecord.floor || "");
      setManualSpot(newRecord.spotNumber || "");
      setManualNotes(newRecord.notes || "");

      saveParkingRecord(newRecord);
      setAppState(AppState.PARKED);
    };
    reader.readAsDataURL(file);
  };

  const handleSkipPhoto = () => {
    if (parkingData) {
      saveParkingRecord(parkingData);
      setAppState(AppState.PARKED);
    }
  };

  // For adding a photo later if skipped or replacing
  const handleAddPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && parkingData) {
       const reader = new FileReader();
       reader.onloadend = () => {
         const base64String = reader.result as string;
         const updated = { ...parkingData, photoBase64: base64String };
         setParkingData(updated);
         saveParkingRecord(updated);
       };
       reader.readAsDataURL(file);
    }
  };

  const handleClearParking = () => {
    if (window.confirm("Are you sure you want to clear your parking location?")) {
      clearParkingRecord();
      setParkingData(null);
      setTempPhoto(null);
      setAppState(AppState.IDLE);
      setEditMode(false);
      setShowTimerSetup(false);
      notificationSentRef.current = false;
    }
  };

  const handleUpdateRecord = () => {
    if (!parkingData) return;
    const updated: ParkingLocation = {
      ...parkingData,
      floor: manualFloor,
      spotNumber: manualSpot,
      notes: manualNotes,
      durationMinutes: timerDuration || undefined
    };
    setParkingData(updated);
    saveParkingRecord(updated);

    // Reset notification if timer changed
    if (timerDuration !== parkingData.durationMinutes) {
      notificationSentRef.current = false;
    }

    setEditMode(false);
    setShowTimerSetup(false);
  };

  const openMap = () => {
    if (!parkingData) return;
    const { latitude, longitude } = parkingData.coords;
    window.open(`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`, '_blank');
  };

  // ---------------- Render Helpers ----------------

  const TimerOptionButton = ({ mins, label }: { mins: number, label: string }) => (
    <button 
      onClick={() => setTimerDuration(mins)}
      className={`px-4 py-3 rounded-xl border font-medium text-sm transition-all ${
        timerDuration === mins 
          ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
          : 'bg-white text-gray-700 border-gray-200 hover:border-indigo-300'
      }`}
    >
      {label}
    </button>
  );

  // ---------------- Render Views ----------------

  const renderIdle = () => (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fade-in">
      <div className="relative">
        <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 rounded-full animate-pulse"></div>
        <div className="bg-white p-6 rounded-3xl shadow-xl relative z-10">
          <Car className="w-16 h-16 text-indigo-600" />
        </div>
      </div>

      <div className="space-y-2">
        <h2 className="text-3xl font-bold text-gray-800">Ready to Park?</h2>
        <p className="text-gray-500 max-w-xs mx-auto">Automatically record your location and use AI to remember your spot number.</p>
      </div>

      <div className="w-full max-w-xs">
        <Button 
          onClick={handleStartParking} 
          className="w-full h-16 text-lg shadow-indigo-500/40 hover:shadow-indigo-500/50"
          icon={<MapPin className="w-6 h-6" />}
        >
          Park Here
        </Button>
      </div>

      <input 
        type="file" 
        accept="image/*" 
        capture="environment"
        ref={fileInputRef}
        onChange={handlePhotoUpload}
        className="hidden"
      />
    </div>
  );

  const renderLocating = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
      <Loader2 className="w-12 h-12 text-indigo-600 animate-spin" />
      <p className="text-lg font-medium text-gray-700">Acquiring GPS Signal...</p>
      <p className="text-sm text-gray-400">Please stand still for better accuracy</p>
    </div>
  );

  const renderAnalyzing = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-6">
      <div className="relative w-full max-w-sm aspect-video rounded-2xl overflow-hidden shadow-lg border-2 border-indigo-100">
        {tempPhoto && (
          <img src={tempPhoto} alt="Parking" className="w-full h-full object-cover opacity-50" />
        )}
        <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[2px]">
          <div className="bg-white/90 p-4 rounded-full shadow-lg">
             <div className="animate-spin text-indigo-600">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                </svg>
             </div>
          </div>
        </div>
      </div>
      <div className="text-center">
        <h3 className="text-xl font-bold text-gray-800 mb-2">Analyzing Image...</h3>
        <p className="text-gray-500 text-sm max-w-xs">Gemini AI is reading floor and spot numbers from your photo.</p>
      </div>
    </div>
  );

  const renderParked = () => {
    if (!parkingData) return null;

    if (editMode || showTimerSetup) {
      return (
        <div className="space-y-6 animate-fade-in pb-12">
           <div className="flex items-center justify-between mb-4">
             <h2 className="text-xl font-bold text-gray-800">{showTimerSetup ? 'Set Timer' : 'Edit Details'}</h2>
             <button onClick={() => { setEditMode(false); setShowTimerSetup(false); }} className="text-gray-500 hover:text-gray-700">Cancel</button>
           </div>

           {showTimerSetup && (
             <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
                <div className="flex items-center mb-4 text-indigo-600">
                  <Clock className="w-5 h-5 mr-2" />
                  <span className="font-semibold">Parking Duration</span>
                </div>
                <div className="grid grid-cols-3 gap-3 mb-4">
                  <TimerOptionButton mins={30} label="30m" />
                  <TimerOptionButton mins={60} label="1h" />
                  <TimerOptionButton mins={90} label="1.5h" />
                  <TimerOptionButton mins={120} label="2h" />
                  <TimerOptionButton mins={180} label="3h" />
                  <TimerOptionButton mins={240} label="4h" />
                </div>
                <div className="flex items-center justify-between">
                   <span className="text-sm text-gray-500">Or clear timer</span>
                   <button onClick={() => setTimerDuration(null)} className="text-sm text-red-500 font-medium px-3 py-1 bg-red-50 rounded-lg">Clear</button>
                </div>
             </div>
           )}

           {(editMode || !showTimerSetup) && (
             <div className="space-y-4">
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Floor Level</label>
                 <input 
                    type="text" 
                    value={manualFloor} 
                    onChange={(e) => setManualFloor(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    placeholder="e.g. B2, Lvl 4"
                 />
               </div>
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Spot Number</label>
                 <input 
                    type="text" 
                    value={manualSpot} 
                    onChange={(e) => setManualSpot(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    placeholder="e.g. 402, A-12"
                 />
               </div>
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Notes / Description</label>
                 <textarea 
                    value={manualNotes} 
                    onChange={(e) => setManualNotes(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all h-24 resize-none"
                    placeholder="Near the elevator..."
                 />
               </div>
               <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Update Photo</label>
                  <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
                    className="hidden" 
                  />
                  <Button 
                    variant="secondary" 
                    onClick={() => editFileInputRef.current?.click()}
                    className="w-full border-dashed"
                    icon={<Camera className="w-4 h-4" />}
                  >
                    Take New Photo
                  </Button>
               </div>
             </div>
           )}

           <Button onClick={handleUpdateRecord} className="w-full mt-6" icon={<Save className="w-4 h-4" />}>
             Save Changes
           </Button>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-fade-in pb-24">
        {/* Header Status */}
        <div className={`rounded-3xl p-6 text-white shadow-xl transition-colors ${isExpired ? 'bg-red-500 shadow-red-200' : 'bg-indigo-600 shadow-indigo-200'}`}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <span className="flex h-3 w-3 relative">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span>
              </span>
              <span className="font-semibold tracking-wide text-sm opacity-90">
                {isExpired ? 'PARKING EXPIRED' : 'CURRENTLY PARKED'}
              </span>
            </div>
            <div className="flex items-center space-x-1 bg-white/20 px-3 py-1 rounded-full text-xs font-medium">
              <Clock className="w-3 h-3" />
              <span>{elapsedTime} elapsed</span>
            </div>
          </div>

          <div className="flex justify-between items-end">
             <div>
               <p className="text-white/70 text-sm mb-1">Floor</p>
               <p className="text-3xl font-bold">{parkingData.floor || "--"}</p>
             </div>
             <div className="text-right">
               <p className="text-white/70 text-sm mb-1">Spot</p>
               <p className="text-3xl font-bold">{parkingData.spotNumber || "--"}</p>
             </div>
          </div>
        </div>

        {/* Timer Card */}
        <div className="bg-white p-1 rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          {parkingData.durationMinutes ? (
             <div className="flex items-center justify-between p-4">
               <div className="flex items-center space-x-3">
                 <div className={`p-2 rounded-lg ${isExpired ? 'bg-red-100 text-red-600' : 'bg-indigo-50 text-indigo-600'}`}>
                   {isExpired ? <AlertTriangle className="w-5 h-5" /> : <Clock className="w-5 h-5" />}
                 </div>
                 <div>
                   <p className="text-xs font-medium text-gray-500 uppercase tracking-wider">Time Remaining</p>
                   <p className={`text-xl font-bold ${isExpired ? 'text-red-600' : 'text-gray-900'}`}>{remainingTime}</p>
                 </div>
               </div>
               <button onClick={() => setShowTimerSetup(true)} className="text-sm font-semibold text-indigo-600 hover:bg-indigo-50 px-3 py-2 rounded-lg transition-colors">
                 Edit
               </button>
             </div>
          ) : (
            <div className="p-4 flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => setShowTimerSetup(true)}>
               <div className="flex items-center space-x-3">
                 <div className="p-2 rounded-lg bg-gray-100 text-gray-500">
                   <Bell className="w-5 h-5" />
                 </div>
                 <div>
                   <p className="text-sm font-semibold text-gray-700">Set Parking Timer</p>
                   <p className="text-xs text-gray-500">Get notified before expiration</p>
                 </div>
               </div>
               <div className="bg-indigo-50 text-indigo-600 p-1.5 rounded-lg">
                 <Plus className="w-4 h-4" />
               </div>
            </div>
          )}
        </div>

        {/* Photo Section */}
        <div className="relative rounded-2xl overflow-hidden shadow-md border border-gray-100 bg-gray-100 min-h-[12rem]">
           {parkingData.photoBase64 ? (
             <>
               <img src={parkingData.photoBase64} alt="Parking Spot" className="w-full h-48 object-cover" />
               <div className="absolute top-2 right-2">
                 <button 
                    onClick={() => setEditMode(true)}
                    className="bg-black/50 hover:bg-black/70 text-white p-2 rounded-full backdrop-blur-sm transition-all"
                 >
                   <Edit2 className="w-4 h-4" />
                 </button>
               </div>
             </>
           ) : (
             <div className="flex flex-col items-center justify-center h-48 space-y-3">
                <p className="text-gray-400 text-sm">No photo recorded</p>
                <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
                    className="hidden" 
                />
                <Button variant="secondary" onClick={() => editFileInputRef.current?.click()} className="text-xs py-2 px-4 h-auto">
                  <Camera className="w-4 h-4 mr-2" /> Add Photo
                </Button>
             </div>
           )}
        </div>

        {/* Location & Actions */}
        <div className="grid grid-cols-2 gap-3">
          <Button variant="secondary" onClick={openMap} className="flex-col py-4 h-auto space-y-2">
             <Navigation className="w-6 h-6 text-blue-500" />
             <span className="text-xs font-medium">Navigate</span>
          </Button>
          <Button variant="secondary" onClick={() => setEditMode(true)} className="flex-col py-4 h-auto space-y-2">
             <Edit2 className="w-6 h-6 text-orange-500" />
             <span className="text-xs font-medium">Edit Notes</span>
          </Button>
        </div>

        {/* Notes Card */}
        {parkingData.notes && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
             <h4 className="text-sm font-semibold text-gray-900 mb-2 flex items-center">
               <MapIcon className="w-4 h-4 mr-2 text-gray-400" />
               Location Notes
             </h4>
             <p className="text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">{parkingData.notes}</p>
          </div>
        )}

        {/* Bottom Action */}
        <div className="fixed bottom-6 left-6 right-6">
           <Button variant="danger" onClick={handleClearParking} className="w-full shadow-lg shadow-red-200" icon={<Trash2 className="w-5 h-5" />}>
             End Parking & Clear
           </Button>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans selection:bg-indigo-100">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl relative overflow-hidden">
        {/* Background Decorations */}
        <div className="absolute top-0 left-0 right-0 h-64 bg-gradient-to-b from-indigo-50/50 to-transparent pointer-events-none"></div>

        {/* Header */}
        <header className="px-6 pt-8 pb-2 relative z-10 flex items-center justify-between">
           <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
             Smart Park AI
           </h1>
        </header>

        {/* Main Content */}
        <main className="px-6 py-4 relative z-10">
          {errorMsg && (
            <div className="mb-6 bg-red-50 border border-red-100 text-red-600 px-4 py-3 rounded-xl text-sm flex items-start">
              <span className="mr-2">⚠️</span>
              {errorMsg}
            </div>
          )}

          {appState === AppState.IDLE && renderIdle()}
          {appState === AppState.LOCATING && renderLocating()}
          {appState === AppState.ANALYZING && renderAnalyzing()}
          {appState === AppState.PARKED && renderParked()}
          {appState === AppState.ERROR && (
             <div className="text-center py-10">
               <p className="text-gray-500 mb-4">Something went wrong.</p>
               <Button onClick={() => setAppState(AppState.IDLE)}>Try Again</Button>
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

export interface GeoLocation {
  latitude: number;
  longitude: number;
  accuracy: number;
}

export interface ParkingLocation {
  id: string;
  timestamp: number;
  coords?: GeoLocation;
  photoBase64?: string;
  notes?: string;
  floor?: string;
  spotNumber?: string;
  aiAnalysis?: string;
  durationMinutes?: number;
}

export enum AppState {
  IDLE = 'IDLE',
  LOCATING = 'LOCATING',
  ANALYZING = 'ANALYZING',
  PARKED = 'PARKED',
  ERROR = 'ERROR'
}

export interface AiAnalysisResult {
  floor: string | null;
  spotNumber: string | null;
  description: string | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Camera, Clock, Navigation, Trash2, Save, Car, Loader2, Map as MapIcon, Edit2, Bell, AlertTriangle, Plus } from 'lucide-react';
import { GeoLocation, ParkingLocation, AppState } from './types';
import { analyzeParkingPhoto } from './services/geminiService';
import { saveParkingRecord, getParkingRecord, clearParkingRecord } from './utils/storage';
import { Button } from './components/Button';
import { InfoCard } from './components/InfoCard';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [parkingData, setParkingData] = useState<ParkingLocation | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Timer state
  const [elapsedTime, setElapsedTime] = useState<string>("0m");
  const [remainingTime, setRemainingTime] = useState<string | null>(null);
  const [isExpired, setIsExpired] = useState(false);

  // UI state
  const [editMode, setEditMode] = useState(false);
  const [showTimerSetup, setShowTimerSetup] = useState(false);

  // Edit form state
  const [manualFloor, setManualFloor] = useState("");
  const [manualSpot, setManualSpot] = useState("");
  const [manualNotes, setManualNotes] = useState("");
  const [timerDuration, setTimerDuration] = useState<number | null>(null); // minutes

  const fileInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);
  const notificationSentRef = useRef(false);
  const isLocatingRef = useRef(false);

  // Load saved data on mount
  useEffect(() => {
    const saved = getParkingRecord();
    if (saved) {
      setParkingData(saved);
      setTimerDuration(saved.durationMinutes || null);
      setAppState(AppState.PARKED);
    }

    // Request notification permission early
    if ('Notification' in window) {
      Notification.requestPermission();
    }
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: number;
    if (appState === AppState.PARKED && parkingData) {
      const updateTimer = () => {
        const now = Date.now();
        const diff = now - parkingData.timestamp;

        // Update Elapsed
        const eMinutes = Math.floor(diff / 60000);
        const eHours = Math.floor(eMinutes / 60);
        if (eHours > 0) {
          setElapsedTime(`${eHours}h ${eMinutes % 60}m`);
        } else {
          setElapsedTime(`${eMinutes}m`);
        }

        // Update Remaining if timer set
        if (parkingData.durationMinutes) {
          const endTime = parkingData.timestamp + (parkingData.durationMinutes * 60000);
          const remainingMs = endTime - now;

          if (remainingMs <= 0) {
            setRemainingTime("Expired");
            setIsExpired(true);
            if (!notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
              new Notification("Parking Meter Expired", { body: "Your parking session has ended." });
              notificationSentRef.current = true;
            }
          } else {
            setIsExpired(false);
            const rMinutes = Math.floor(remainingMs / 60000);
            const rHours = Math.floor(rMinutes / 60);
            const displayMin = rMinutes % 60;

            setRemainingTime(`${rHours}:${displayMin.toString().padStart(2, '0')}`);

            // Notify if 15 mins left
            if (rMinutes <= 15 && !notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
               new Notification("Parking Expiring Soon", { body: `You have ${rMinutes} minutes left.` });
               notificationSentRef.current = true;
            }
          }
        } else {
          setRemainingTime(null);
          setIsExpired(false);
        }
      };

      updateTimer();
      interval = window.setInterval(updateTimer, 30000); // Update every 30s
    }
    return () => clearInterval(interval);
  }, [appState, parkingData]);

  const handleStartParking = async () => {
    setErrorMsg(null);
    setAppState(AppState.LOCATING);
    isLocatingRef.current = true;

    if (!navigator.geolocation) {
      // If no geo support, go straight to manual
      handleManualLocation();
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        if (!isLocatingRef.current) return;
        isLocatingRef.current = false;

        const coords: GeoLocation = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        };

        // Temporarily store coords and ask for photo
        setParkingData({
          id: Date.now().toString(),
          timestamp: Date.now(),
          coords: coords
        } as ParkingLocation);

        // Trigger file input immediately after location found for smoother UX
        if (fileInputRef.current) {
          fileInputRef.current.click();
        }
      },
      (error) => {
        if (!isLocatingRef.current) return;
        isLocatingRef.current = false;

        console.warn("Geolocation error", error);
        // Instead of showing error state, let's just fall back to manual mode gracefully or show a message
        setErrorMsg(`Location failed (${error.message}). Switched to manual mode.`);
        handleManualLocation();
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  };

  const handleManualLocation = () => {
    isLocatingRef.current = false;
    // Create record without coords
    setParkingData({
      id: Date.now().toString(),
      timestamp: Date.now(),
      // coords undefined
    } as ParkingLocation);

    // Proceed to photo
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) {
        // If user cancelled photo picker in manual mode, they are parked but without photo or coords?
        // Let's assume they want to be parked.
        if (parkingData) {
            saveParkingRecord(parkingData);
            setAppState(AppState.PARKED);
        }
        return;
    }
    if (!parkingData) return;

    processAndSavePhoto(file);
  };

  const processAndSavePhoto = (file: File) => {
    // Convert to base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      setTempPhoto(base64String);
      setAppState(AppState.ANALYZING);

      // Analyze with Gemini
      const analysis = await analyzeParkingPhoto(base64String);

      const newRecord: ParkingLocation = {
        ...parkingData!,
        photoBase64: base64String,
        floor: analysis.floor || undefined,
        spotNumber: analysis.spotNumber || undefined,
        aiAnalysis: analysis.description || undefined,
        notes: analysis.description || undefined
      };

      setParkingData(newRecord);
      setManualFloor(newRecord.floor || "");
      setManualSpot(newRecord.spotNumber || "");
      setManualNotes(newRecord.notes || "");

      saveParkingRecord(newRecord);
      setAppState(AppState.PARKED);
    };
    reader.readAsDataURL(file);
  };

  const handleSkipPhoto = () => {
    if (parkingData) {
      saveParkingRecord(parkingData);
      setAppState(AppState.PARKED);
    }
  };

  // For adding a photo later if skipped or replacing
  const handleAddPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && parkingData) {
       const reader = new FileReader();
       reader.onloadend = () => {
         const base64String = reader.result as string;
         const updated = { ...parkingData, photoBase64: base64String };
         setParkingData(updated);
         saveParkingRecord(updated);
       };
       reader.readAsDataURL(file);
    }
  };

  const handleClearParking = () => {
    if (window.confirm("Are you sure you want to clear your parking location?")) {
      clearParkingRecord();
      setParkingData(null);
      setTempPhoto(null);
      setAppState(AppState.IDLE);
      setEditMode(false);
      setShowTimerSetup(false);
      notificationSentRef.current = false;
    }
  };

  const handleUpdateRecord = () => {
    if (!parkingData) return;
    const updated: ParkingLocation = {
      ...parkingData,
      floor: manualFloor,
      spotNumber: manualSpot,
      notes: manualNotes,
      durationMinutes: timerDuration || undefined
    };
    setParkingData(updated);
    saveParkingRecord(updated);

    // Reset notification if timer changed
    if (timerDuration !== parkingData.durationMinutes) {
      notificationSentRef.current = false;
    }

    setEditMode(false);
    setShowTimerSetup(false);
  };

  const openMap = () => {
    if (!parkingData) return;
    if (!parkingData.coords) {
        alert("No GPS location saved for this spot.");
        return;
    }
    const { latitude, longitude } = parkingData.coords;
    window.open(`https://www.google.com/maps/search/?api=1&query=${latitude},${longitude}`, '_blank');
  };

  // ---------------- Render Helpers ----------------

  const TimerOptionButton = ({ mins, label }: { mins: number, label: string }) => (
    <button 
      onClick={() => setTimerDuration(mins)}
      className={`px-4 py-3 rounded-xl border font-medium text-sm transition-all ${
        timerDuration === mins 
          ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
          : 'bg-white text-gray-700 border-gray-200 hover:border-indigo-300'
      }`}
    >
      {label}
    </button>
  );

  // ---------------- Render Views ----------------

  const renderIdle = () => (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fade-in">
      <div className="relative">
        <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 rounded-full animate-pulse"></div>
        <div className="bg-white p-6 rounded-3xl shadow-xl relative z-10">
          <Car className="w-16 h-16 text-indigo-600" />
        </div>
      </div>

      <div className="space-y-2">
        <h2 className="text-3xl font-bold text-gray-800">Ready to Park?</h2>
        <p className="text-gray-500 max-w-xs mx-auto">Automatically record your location and use AI to remember your spot number.</p>
      </div>

      <div className="w-full max-w-xs">
        <Button 
          onClick={handleStartParking} 
          className="w-full h-16 text-lg shadow-indigo-500/40 hover:shadow-indigo-500/50"
          icon={<MapPin className="w-6 h-6" />}
        >
          Park Here
        </Button>
      </div>

      <input 
        type="file" 
        accept="image/*" 
        capture="environment"
        ref={fileInputRef}
        onChange={handlePhotoUpload}
        className="hidden"
      />
    </div>
  );

  const renderLocating = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
      <Loader2 className="w-12 h-12 text-indigo-600 animate-spin" />
      <p className="text-lg font-medium text-gray-700">Acquiring GPS Signal...</p>
      <p className="text-sm text-gray-400">Please stand still for better accuracy</p>

      <Button 
        variant="ghost" 
        onClick={handleManualLocation} 
        className="mt-4 text-indigo-600 bg-indigo-50 hover:bg-indigo-100"
      >
        Skip Location & Record Manually
      </Button>
    </div>
  );

  const renderAnalyzing = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-6">
      <div className="relative w-full max-w-sm aspect-video rounded-2xl overflow-hidden shadow-lg border-2 border-indigo-100">
        {tempPhoto && (
          <img src={tempPhoto} alt="Parking" className="w-full h-full object-cover opacity-50" />
        )}
        <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[2px]">
          <div className="bg-white/90 p-4 rounded-full shadow-lg">
             <div className="animate-spin text-indigo-600">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                </svg>
             </div>
          </div>
        </div>
      </div>
      <div className="text-center">
        <h3 className="text-xl font-bold text-gray-800 mb-2">Analyzing Image...</h3>
        <p className="text-gray-500 text-sm max-w-xs">Gemini AI is reading floor and spot numbers from your photo.</p>
      </div>
    </div>
  );

  const renderParked = () => {
    if (!parkingData) return null;

    if (editMode || showTimerSetup) {
      return (
        <div className="space-y-6 animate-fade-in pb-12">
           <div className="flex items-center justify-between mb-4">
             <h2 className="text-xl font-bold text-gray-800">{showTimerSetup ? 'Set Timer' : 'Edit Details'}</h2>
             <button onClick={() => { setEditMode(false); setShowTimerSetup(false); }} className="text-gray-500 hover:text-gray-700">Cancel</button>
           </div>

           {showTimerSetup && (
             <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
                <div className="flex items-center mb-4 text-indigo-600">
                  <Clock className="w-5 h-5 mr-2" />
                  <span className="font-semibold">Parking Duration</span>
                </div>
                <div className="grid grid-cols-3 gap-3 mb-4">
                  <TimerOptionButton mins={30} label="30m" />
                  <TimerOptionButton mins={60} label="1h" />
                  <TimerOptionButton mins={90} label="1.5h" />
                  <TimerOptionButton mins={120} label="2h" />
                  <TimerOptionButton mins={180} label="3h" />
                  <TimerOptionButton mins={240} label="4h" />
                </div>
                <div className="flex items-center justify-between">
                   <span className="text-sm text-gray-500">Or clear timer</span>
                   <button onClick={() => setTimerDuration(null)} className="text-sm text-red-500 font-medium px-3 py-1 bg-red-50 rounded-lg">Clear</button>
                </div>
             </div>
           )}

           {(editMode || !showTimerSetup) && (
             <div className="space-y-4">
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Floor Level</label>
                 <input 
                    type="text" 
                    value={manualFloor} 
                    onChange={(e) => setManualFloor(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    placeholder="e.g. B2, Lvl 4"
                 />
               </div>
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Spot Number</label>
                 <input 
                    type="text" 
                    value={manualSpot} 
                    onChange={(e) => setManualSpot(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                    placeholder="e.g. 402, A-12"
                 />
               </div>
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Notes / Description</label>
                 <textarea 
                    value={manualNotes} 
                    onChange={(e) => setManualNotes(e.target.value)}
                    className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all h-24 resize-none"
                    placeholder="Near the elevator..."
                 />
               </div>
               <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Update Photo</label>
                  <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
                    className="hidden" 
                  />
                  <Button 
                    variant="secondary" 
                    onClick={() => editFileInputRef.current?.click()}
                    className="w-full border-dashed"
                    icon={<Camera className="w-4 h-4" />}
                  >
                    Take New Photo
                  </Button>
               </div>
             </div>
           )}

           <Button onClick={handleUpdateRecord} className="w-full mt-6" icon={<Save className="w-4 h-4" />}>
             Save Changes
           </Button>
        </div>
      );
    }

    return (
      <div className="space-y-6 animate-fade-in pb-24">
        {/* Header Status */}
        <div className={`rounded-3xl p-6 text-white shadow-xl transition-colors ${isExpired ? 'bg-red-500 shadow-red-200' : 'bg-indigo-600 shadow-indigo-200'}`}>
          <div className="flex items-center justify-between mb-4">
            <div className="flex items-center space-x-2">
              <span className="flex h-3 w-3 relative">
                <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-white opacity-75"></span>
                <span className="relative inline-flex rounded-full h-3 w-3 bg-white"></span>
              </span>
              <span className="font-semibold tracking-wide text-sm opacity-90">
                {isExpired ? 'PARKING EXPIRED' : 'CURRENTLY PARKED'}
              </span>
            </div>
            <div className="flex items-center space-x-1 bg-white/20 px-3 py-1 rounded-full text-xs font-medium">
              <Clock className="w-3 h-3" />
              <span>{elapsedTime} elapsed</span>
            </div>
          </div>

          <div className="flex justify-between items-end">
             <div>
               <p className="text-white/70 text-sm mb-1">Floor</p>
               <p className="text-3xl font-bold">{parkingData.floor || "--"}</p>
             </div>
             <div className="text-right">
               <p className="text-white/70 text-sm mb-1">Spot</p>
               <p className="text-3xl font-bold">{parkingData.spotNumber || "--"}</p>
             </div>
          </div>
        </div>

        {/* Timer Card */}
        <div className="bg-white p-1 rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          {parkingData.durationMinutes ? (
             <div className="flex items-center justify-between p-4">
               <div className="flex items-center space-x-3">
                 <div className={`p-2 rounded-lg ${isExpired ? 'bg-red-100 text-red-600' : 'bg-indigo-50 text-indigo-600'}`}>
                   {isExpired ? <AlertTriangle className="w-5 h-5" /> : <Clock className="w-5 h-5" />}
                 </div>
                 <div>
                   <p className="text-xs font-medium text-gray-500 uppercase tracking-wider">Time Remaining</p>
                   <p className={`text-xl font-bold ${isExpired ? 'text-red-600' : 'text-gray-900'}`}>{remainingTime}</p>
                 </div>
               </div>
               <button onClick={() => setShowTimerSetup(true)} className="text-sm font-semibold text-indigo-600 hover:bg-indigo-50 px-3 py-2 rounded-lg transition-colors">
                 Edit
               </button>
             </div>
          ) : (
            <div className="p-4 flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => setShowTimerSetup(true)}>
               <div className="flex items-center space-x-3">
                 <div className="p-2 rounded-lg bg-gray-100 text-gray-500">
                   <Bell className="w-5 h-5" />
                 </div>
                 <div>
                   <p className="text-sm font-semibold text-gray-700">Set Parking Timer</p>
                   <p className="text-xs text-gray-500">Get notified before expiration</p>
                 </div>
               </div>
               <div className="bg-indigo-50 text-indigo-600 p-1.5 rounded-lg">
                 <Plus className="w-4 h-4" />
               </div>
            </div>
          )}
        </div>

        {/* Photo Section */}
        <div className="relative rounded-2xl overflow-hidden shadow-md border border-gray-100 bg-gray-100 min-h-[12rem]">
           {parkingData.photoBase64 ? (
             <>
               <img src={parkingData.photoBase64} alt="Parking Spot" className="w-full h-48 object-cover" />
               <div className="absolute top-2 right-2">
                 <button 
                    onClick={() => setEditMode(true)}
                    className="bg-black/50 hover:bg-black/70 text-white p-2 rounded-full backdrop-blur-sm transition-all"
                 >
                   <Edit2 className="w-4 h-4" />
                 </button>
               </div>
             </>
           ) : (
             <div className="flex flex-col items-center justify-center h-48 space-y-3">
                <p className="text-gray-400 text-sm">No photo recorded</p>
                <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
                    className="hidden" 
                />
                <Button variant="secondary" onClick={() => editFileInputRef.current?.click()} className="text-xs py-2 px-4 h-auto">
                  <Camera className="w-4 h-4 mr-2" /> Add Photo
                </Button>
             </div>
           )}
        </div>

        {/* Location & Actions */}
        <div className="grid grid-cols-2 gap-3">
          <Button 
            variant="secondary" 
            onClick={openMap} 
            disabled={!parkingData.coords}
            className={`flex-col py-4 h-auto space-y-2 ${!parkingData.coords ? 'opacity-50 grayscale' : ''}`}
          >
             <Navigation className="w-6 h-6 text-blue-500" />
             <span className="text-xs font-medium">{parkingData.coords ? 'Navigate' : 'No Location'}</span>
          </Button>
          <Button variant="secondary" onClick={() => setEditMode(true)} className="flex-col py-4 h-auto space-y-2">
             <Edit2 className="w-6 h-6 text-orange-500" />
             <span className="text-xs font-medium">Edit Notes</span>
          </Button>
        </div>

        {/* Notes Card */}
        {parkingData.notes && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
             <h4 className="text-sm font-semibold text-gray-900 mb-2 flex items-center">
               <MapIcon className="w-4 h-4 mr-2 text-gray-400" />
               Location Notes
             </h4>
             <p className="text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">{parkingData.notes}</p>
          </div>
        )}

        {/* Bottom Action */}
        <div className="fixed bottom-6 left-6 right-6">
           <Button variant="danger" onClick={handleClearParking} className="w-full shadow-lg shadow-red-200" icon={<Trash2 className="w-5 h-5" />}>
             End Parking & Clear
           </Button>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans selection:bg-indigo-100">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl relative overflow-hidden">
        {/* Background Decorations */}
        <div className="absolute top-0 left-0 right-0 h-64 bg-gradient-to-b from-indigo-50/50 to-transparent pointer-events-none"></div>

        {/* Header */}
        <header className="px-6 pt-8 pb-2 relative z-10 flex items-center justify-between">
           <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
             Smart Park AI
           </h1>
        </header>

        {/* Main Content */}
        <main className="px-6 py-4 relative z-10">
          {errorMsg && (
            <div className="mb-6 bg-red-50 border border-red-100 text-red-600 px-4 py-3 rounded-xl text-sm flex items-start">
              <span className="mr-2">⚠️</span>
              {errorMsg}
            </div>
          )}

          {appState === AppState.IDLE && renderIdle()}
          {appState === AppState.LOCATING && renderLocating()}
          {appState === AppState.ANALYZING && renderAnalyzing()}
          {appState === AppState.PARKED && renderParked()}
          {appState === AppState.ERROR && (
             <div className="text-center py-10">
               <p className="text-gray-500 mb-4">Something went wrong.</p>
               <Button onClick={() => setAppState(AppState.IDLE)}>Try Again</Button>
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

export interface GeoLocation {
  latitude: number;
  longitude: number;
  accuracy: number;
}

export interface ParkingLocation {
  id: string;
  timestamp: number;
  coords?: GeoLocation;
  locationName?: string;
  photoBase64?: string;
  notes?: string;
  floor?: string;
  spotNumber?: string;
  aiAnalysis?: string;
  durationMinutes?: number;
}

export enum AppState {
  IDLE = 'IDLE',
  LOCATING = 'LOCATING',
  ANALYZING = 'ANALYZING',
  PARKED = 'PARKED',
  ERROR = 'ERROR'
}

export interface AiAnalysisResult {
  floor: string | null;
  spotNumber: string | null;
  description: string | null;
}

import React, { useState, useEffect, useRef } from 'react';
import { MapPin, Camera, Clock, Navigation, Trash2, Save, Car, Loader2, Map as MapIcon, Edit2, Bell, AlertTriangle, Plus, Type } from 'lucide-react';
import { GeoLocation, ParkingLocation, AppState } from './types';
import { analyzeParkingPhoto } from './services/geminiService';
import { saveParkingRecord, getParkingRecord, clearParkingRecord } from './utils/storage';
import { Button } from './components/Button';
import { InfoCard } from './components/InfoCard';

const App: React.FC = () => {
  const [appState, setAppState] = useState<AppState>(AppState.IDLE);
  const [parkingData, setParkingData] = useState<ParkingLocation | null>(null);
  const [tempPhoto, setTempPhoto] = useState<string | null>(null);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  // Timer state
  const [elapsedTime, setElapsedTime] = useState<string>("0m");
  const [remainingTime, setRemainingTime] = useState<string | null>(null);
  const [isExpired, setIsExpired] = useState(false);

  // UI state
  const [editMode, setEditMode] = useState(false);
  const [showTimerSetup, setShowTimerSetup] = useState(false);

  // Edit form state
  const [manualFloor, setManualFloor] = useState("");
  const [manualSpot, setManualSpot] = useState("");
  const [manualNotes, setManualNotes] = useState("");
  const [manualLocationName, setManualLocationName] = useState("");
  const [timerDuration, setTimerDuration] = useState<number | null>(null); // minutes

  const fileInputRef = useRef<HTMLInputElement>(null);
  const editFileInputRef = useRef<HTMLInputElement>(null);
  const notificationSentRef = useRef(false);
  const isLocatingRef = useRef(false);

  // Load saved data on mount
  useEffect(() => {
    const saved = getParkingRecord();
    if (saved) {
      setParkingData(saved);
      setTimerDuration(saved.durationMinutes || null);
      setManualFloor(saved.floor || "");
      setManualSpot(saved.spotNumber || "");
      setManualNotes(saved.notes || "");
      setManualLocationName(saved.locationName || "");
      setAppState(AppState.PARKED);
    }

    // Request notification permission early
    if ('Notification' in window) {
      Notification.requestPermission();
    }
  }, []);

  // Timer effect
  useEffect(() => {
    let interval: number;
    if (appState === AppState.PARKED && parkingData) {
      const updateTimer = () => {
        const now = Date.now();
        const diff = now - parkingData.timestamp;

        // Update Elapsed
        const eMinutes = Math.floor(diff / 60000);
        const eHours = Math.floor(eMinutes / 60);
        if (eHours > 0) {
          setElapsedTime(`${eHours}h ${eMinutes % 60}m`);
        } else {
          setElapsedTime(`${eMinutes}m`);
        }

        // Update Remaining if timer set
        if (parkingData.durationMinutes) {
          const endTime = parkingData.timestamp + (parkingData.durationMinutes * 60000);
          const remainingMs = endTime - now;

          if (remainingMs <= 0) {
            setRemainingTime("Expired");
            setIsExpired(true);
            if (!notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
              new Notification("Parking Meter Expired", { body: "Your parking session has ended." });
              notificationSentRef.current = true;
            }
          } else {
            setIsExpired(false);
            const rMinutes = Math.floor(remainingMs / 60000);
            const rHours = Math.floor(rMinutes / 60);
            const displayMin = rMinutes % 60;

            setRemainingTime(`${rHours}:${displayMin.toString().padStart(2, '0')}`);

            // Notify if 15 mins left
            if (rMinutes <= 15 && !notificationSentRef.current && 'Notification' in window && Notification.permission === 'granted') {
               new Notification("Parking Expiring Soon", { body: `You have ${rMinutes} minutes left.` });
               notificationSentRef.current = true;
            }
          }
        } else {
          setRemainingTime(null);
          setIsExpired(false);
        }
      };

      updateTimer();
      interval = window.setInterval(updateTimer, 30000); // Update every 30s
    }
    return () => clearInterval(interval);
  }, [appState, parkingData]);

  const handleStartParking = async () => {
    setErrorMsg(null);
    setAppState(AppState.LOCATING);
    isLocatingRef.current = true;

    if (!navigator.geolocation) {
      // If no geo support, go straight to manual
      handleManualLocation();
      return;
    }

    navigator.geolocation.getCurrentPosition(
      (position) => {
        if (!isLocatingRef.current) return;
        isLocatingRef.current = false;

        const coords: GeoLocation = {
          latitude: position.coords.latitude,
          longitude: position.coords.longitude,
          accuracy: position.coords.accuracy,
        };

        // Temporarily store coords and ask for photo
        setParkingData({
          id: Date.now().toString(),
          timestamp: Date.now(),
          coords: coords
        } as ParkingLocation);

        // Trigger file input immediately after location found for smoother UX
        if (fileInputRef.current) {
          fileInputRef.current.click();
        }
      },
      (error) => {
        if (!isLocatingRef.current) return;
        isLocatingRef.current = false;

        console.warn("Geolocation error", error);
        // Instead of showing error state, let's just fall back to manual mode gracefully or show a message
        setErrorMsg(`Location failed (${error.message}). Switched to manual mode.`);
        handleManualLocation();
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  };

  const handleManualLocation = () => {
    isLocatingRef.current = false;
    setErrorMsg(null);
    // Create record without coords
    setParkingData({
      id: Date.now().toString(),
      timestamp: Date.now(),
      // coords undefined
    } as ParkingLocation);

    // Proceed to photo
    if (fileInputRef.current) {
      fileInputRef.current.click();
    }
  };

  const handlePhotoUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) {
        // If user cancelled photo picker in manual mode, they are parked but without photo or coords?
        // Let's assume they want to be parked.
        if (parkingData) {
            saveParkingRecord(parkingData);
            setAppState(AppState.PARKED);
            // If manual entry and no photo, auto-open edit mode to prompt for location name
            if (!parkingData.coords) {
              setEditMode(true);
            }
        }
        return;
    }
    if (!parkingData) return;

    processAndSavePhoto(file);
  };

  const processAndSavePhoto = (file: File) => {
    // Convert to base64
    const reader = new FileReader();
    reader.onloadend = async () => {
      const base64String = reader.result as string;
      setTempPhoto(base64String);
      setAppState(AppState.ANALYZING);

      // Analyze with Gemini
      const analysis = await analyzeParkingPhoto(base64String);

      const newRecord: ParkingLocation = {
        ...parkingData!,
        photoBase64: base64String,
        floor: analysis.floor || undefined,
        spotNumber: analysis.spotNumber || undefined,
        aiAnalysis: analysis.description || undefined,
        notes: analysis.description || undefined
      };

      setParkingData(newRecord);
      setManualFloor(newRecord.floor || "");
      setManualSpot(newRecord.spotNumber || "");
      setManualNotes(newRecord.notes || "");
      setManualLocationName(""); // Reset or keep empty

      saveParkingRecord(newRecord);
      setAppState(AppState.PARKED);
    };
    reader.readAsDataURL(file);
  };

  const handleAddPhoto = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file && parkingData) {
       const reader = new FileReader();
       reader.onloadend = () => {
         const base64String = reader.result as string;
         const updated = { ...parkingData, photoBase64: base64String };
         setParkingData(updated);
         saveParkingRecord(updated);
       };
       reader.readAsDataURL(file);
    }
  };

  const handleClearParking = () => {
    if (window.confirm("Are you sure you want to clear your parking location?")) {
      clearParkingRecord();
      setParkingData(null);
      setTempPhoto(null);
      setAppState(AppState.IDLE);
      setEditMode(false);
      setShowTimerSetup(false);
      notificationSentRef.current = false;
      setManualFloor("");
      setManualSpot("");
      setManualNotes("");
      setManualLocationName("");
    }
  };

  const handleUpdateRecord = () => {
    if (!parkingData) return;
    const updated: ParkingLocation = {
      ...parkingData,
      floor: manualFloor,
      spotNumber: manualSpot,
      notes: manualNotes,
      locationName: manualLocationName,
      durationMinutes: timerDuration || undefined
    };
    setParkingData(updated);
    saveParkingRecord(updated);

    // Reset notification if timer changed
    if (timerDuration !== parkingData.durationMinutes) {
      notificationSentRef.current = false;
    }

    setEditMode(false);
    setShowTimerSetup(false);
  };

  const openMap = () => {
    if (!parkingData) return;

    let query = "";
    if (parkingData.coords) {
      query = `${parkingData.coords.latitude},${parkingData.coords.longitude}`;
    } else if (parkingData.locationName) {
      query = encodeURIComponent(parkingData.locationName);
    }

    if (query) {
      window.open(`https://www.google.com/maps/search/?api=1&query=${query}`, '_blank');
    } else {
      alert("No location data (GPS or Address) to navigate to.");
    }
  };

  // ---------------- Render Helpers ----------------

  const TimerOptionButton = ({ mins, label }: { mins: number, label: string }) => (
    <button 
      onClick={() => setTimerDuration(mins)}
      className={`px-4 py-3 rounded-xl border font-medium text-sm transition-all ${
        timerDuration === mins 
          ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' 
          : 'bg-white text-gray-700 border-gray-200 hover:border-indigo-300'
      }`}
    >
      {label}
    </button>
  );

  // ---------------- Render Views ----------------

  const renderIdle = () => (
    <div className="flex flex-col items-center justify-center min-h-[60vh] text-center space-y-8 animate-fade-in">
      <div className="relative">
        <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20 rounded-full animate-pulse"></div>
        <div className="bg-white p-6 rounded-3xl shadow-xl relative z-10">
          <Car className="w-16 h-16 text-indigo-600" />
        </div>
      </div>

      <div className="space-y-2">
        <h2 className="text-3xl font-bold text-gray-800">Ready to Park?</h2>
        <p className="text-gray-500 max-w-xs mx-auto">Choose how you want to save your parking location.</p>
      </div>

      <div className="w-full max-w-xs space-y-3">
        <Button 
          onClick={handleStartParking} 
          className="w-full h-14 text-lg shadow-indigo-500/40 hover:shadow-indigo-500/50"
          icon={<MapPin className="w-5 h-5" />}
        >
          Auto Detect Location
        </Button>

        <Button 
          variant="secondary"
          onClick={handleManualLocation} 
          className="w-full h-14 text-lg"
          icon={<Edit2 className="w-5 h-5" />}
        >
          Manual Entry
        </Button>
      </div>

      <input 
        type="file" 
        accept="image/*" 
        capture="environment"
        ref={fileInputRef}
        onChange={handlePhotoUpload}
        className="hidden"
      />
    </div>
  );

  const renderLocating = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-4">
      <Loader2 className="w-12 h-12 text-indigo-600 animate-spin" />
      <p className="text-lg font-medium text-gray-700">Acquiring GPS Signal...</p>
      <p className="text-sm text-gray-400">Please stand still for better accuracy</p>

      <Button 
        variant="ghost" 
        onClick={handleManualLocation} 
        className="mt-4 text-indigo-600 bg-indigo-50 hover:bg-indigo-100"
      >
        Skip & Enter Manually
      </Button>
    </div>
  );

  const renderAnalyzing = () => (
    <div className="flex flex-col items-center justify-center min-h-[50vh] space-y-6">
      <div className="relative w-full max-w-sm aspect-video rounded-2xl overflow-hidden shadow-lg border-2 border-indigo-100">
        {tempPhoto && (
          <img src={tempPhoto} alt="Parking" className="w-full h-full object-cover opacity-50" />
        )}
        <div className="absolute inset-0 flex items-center justify-center bg-black/10 backdrop-blur-[2px]">
          <div className="bg-white/90 p-4 rounded-full shadow-lg">
             <div className="animate-spin text-indigo-600">
                <svg className="w-8 h-8" fill="none" viewBox="0 0 24 24">
                  <path stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
                </svg>
             </div>
          </div>
        </div>
      </div>
      <div className="text-center">
        <h3 className="text-xl font-bold text-gray-800 mb-2">Analyzing Image...</h3>
        <p className="text-gray-500 text-sm max-w-xs">Gemini AI is reading floor and spot numbers from your photo.</p>
      </div>
    </div>
  );

  const renderParked = () => {
    if (!parkingData) return null;

    if (editMode || showTimerSetup) {
      return (
        <div className="space-y-6 animate-fade-in pb-12">
           <div className="flex items-center justify-between mb-4">
             <h2 className="text-xl font-bold text-gray-800">{showTimerSetup ? 'Set Timer' : 'Edit Details'}</h2>
             <button onClick={() => { setEditMode(false); setShowTimerSetup(false); }} className="text-gray-500 hover:text-gray-700">Cancel</button>
           </div>

           {showTimerSetup && (
             <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100 mb-6">
