                  <TimerOptionButton mins={60} label="1h" />
                  <TimerOptionButton mins={90} label="1.5h" />
                  <TimerOptionButton mins={120} label="2h" />
                  <TimerOptionButton mins={180} label="3h" />
                  <TimerOptionButton mins={240} label="4h" />
                </div>
                <div className="flex items-center justify-between">
                   <span className="text-sm text-gray-500">Or clear timer</span>
