                    placeholder="e.g. City Mall, Level 3"
                 />
                 <p className="text-xs text-gray-500 mt-1">Used for navigation if GPS is unavailable.</p>
               </div>
               <div className="grid grid-cols-2 gap-3">
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Floor Level</label>
                    <input 
                        type="text" 
                        value={manualFloor} 
                        onChange={(e) => setManualFloor(e.target.value)}
