                        placeholder="e.g. B2"
                    />
                  </div>
                  <div>
                    <label className="block text-sm font-medium text-gray-700 mb-1">Spot Number</label>
                    <input 
                        type="text" 
                        value={manualSpot} 
                        onChange={(e) => setManualSpot(e.target.value)}
                        className="w-full p-3 rounded-xl border border-gray-200 focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 outline-none transition-all"
                        placeholder="e.g. 402"
                    />
                  </div>
               </div>
               <div>
                 <label className="block text-sm font-medium text-gray-700 mb-1">Notes / Description</label>
                 <textarea 
                    value={manualNotes} 
                    onChange={(e) => setManualNotes(e.target.value)}
