               </div>
               <div>
                  <label className="block text-sm font-medium text-gray-700 mb-2">Update Photo</label>
                  <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
