        {/* Timer Card */}
        <div className="bg-white p-1 rounded-2xl shadow-sm border border-gray-100 overflow-hidden">
          {parkingData.durationMinutes ? (
             <div className="flex items-center justify-between p-4">
               <div className="flex items-center space-x-3">
                 <div className={`p-2 rounded-lg ${isExpired ? 'bg-red-100 text-red-600' : 'bg-indigo-50 text-indigo-600'}`}>
                   {isExpired ? <AlertTriangle className="w-5 h-5" /> : <Clock className="w-5 h-5" />}
                 </div>
                 <div>
                   <p className="text-xs font-medium text-gray-500 uppercase tracking-wider">Time Remaining</p>
                   <p className={`text-xl font-bold ${isExpired ? 'text-red-600' : 'text-gray-900'}`}>{remainingTime}</p>
                 </div>
               </div>
               <button onClick={() => setShowTimerSetup(true)} className="text-sm font-semibold text-indigo-600 hover:bg-indigo-50 px-3 py-2 rounded-lg transition-colors">
                 Edit
               </button>
             </div>
          ) : (
            <div className="p-4 flex items-center justify-between cursor-pointer hover:bg-gray-50 transition-colors" onClick={() => setShowTimerSetup(true)}>
               <div className="flex items-center space-x-3">
                 <div className="p-2 rounded-lg bg-gray-100 text-gray-500">
                   <Bell className="w-5 h-5" />
                 </div>
                 <div>
                   <p className="text-sm font-semibold text-gray-700">Set Parking Timer</p>
                   <p className="text-xs text-gray-500">Get notified before expiration</p>
                 </div>
               </div>
               <div className="bg-indigo-50 text-indigo-600 p-1.5 rounded-lg">
                 <Plus className="w-4 h-4" />
               </div>
            </div>
          )}
        </div>

        {/* Photo Section */}
        <div className="relative rounded-2xl overflow-hidden shadow-md border border-gray-100 bg-gray-100 min-h-[12rem]">
           {parkingData.photoBase64 ? (
             <>
               <img src={parkingData.photoBase64} alt="Parking Spot" className="w-full h-48 object-cover" />
               <div className="absolute top-2 right-2">
                 <button 
                    onClick={() => setEditMode(true)}
                    className="bg-black/50 hover:bg-black/70 text-white p-2 rounded-full backdrop-blur-sm transition-all"
                 >
                   <Edit2 className="w-4 h-4" />
                 </button>
               </div>
             </>
           ) : (
             <div className="flex flex-col items-center justify-center h-48 space-y-3">
                <p className="text-gray-400 text-sm">No photo recorded</p>
                <input 
                    type="file" 
                    accept="image/*" 
                    capture="environment"
                    ref={editFileInputRef}
                    onChange={handleAddPhoto}
                    className="hidden" 
                />
                <Button variant="secondary" onClick={() => editFileInputRef.current?.click()} className="text-xs py-2 px-4 h-auto">
                  <Camera className="w-4 h-4 mr-2" /> Add Photo
                </Button>
             </div>
           )}
        </div>

        {/* Location & Actions */}
        <div className="grid grid-cols-2 gap-3">
          <Button 
            variant="secondary" 
            onClick={openMap} 
            disabled={!canNavigate}
            className={`flex-col py-4 h-auto space-y-2 ${!canNavigate ? 'opacity-50 grayscale' : ''}`}
          >
             <Navigation className="w-6 h-6 text-blue-500" />
             <span className="text-xs font-medium">{canNavigate ? 'Navigate' : 'No Location'}</span>
          </Button>
          <Button variant="secondary" onClick={() => setEditMode(true)} className="flex-col py-4 h-auto space-y-2">
             <Edit2 className="w-6 h-6 text-orange-500" />
             <span className="text-xs font-medium">Edit Notes</span>
          </Button>
        </div>

        {/* Notes Card */}
        {parkingData.notes && (
          <div className="bg-white p-5 rounded-2xl shadow-sm border border-gray-100">
             <h4 className="text-sm font-semibold text-gray-900 mb-2 flex items-center">
               <Type className="w-4 h-4 mr-2 text-gray-400" />
               Notes
             </h4>
             <p className="text-gray-600 text-sm leading-relaxed whitespace-pre-wrap">{parkingData.notes}</p>
          </div>
        )}

        {/* Bottom Action */}
        <div className="fixed bottom-6 left-6 right-6">
           <Button variant="danger" onClick={handleClearParking} className="w-full shadow-lg shadow-red-200" icon={<Trash2 className="w-5 h-5" />}>
             End Parking & Clear
           </Button>
        </div>
      </div>
    );
  };

  return (
    <div className="min-h-screen bg-gray-50 text-gray-900 font-sans selection:bg-indigo-100">
      <div className="max-w-md mx-auto min-h-screen bg-white shadow-2xl relative overflow-hidden">
        {/* Background Decorations */}
        <div className="absolute top-0 left-0 right-0 h-64 bg-gradient-to-b from-indigo-50/50 to-transparent pointer-events-none"></div>

        {/* Header */}
        <header className="px-6 pt-8 pb-2 relative z-10 flex items-center justify-between">
           <h1 className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-indigo-600 to-violet-600">
             Smart Park AI
           </h1>
        </header>

        {/* Main Content */}
        <main className="px-6 py-4 relative z-10">
          {errorMsg && (
            <div className="mb-6 bg-red-50 border border-red-100 text-red-600 px-4 py-3 rounded-xl text-sm flex items-start">
              <span className="mr-2">⚠️</span>
              {errorMsg}
            </div>
          )}

          {appState === AppState.IDLE && renderIdle()}
          {appState === AppState.LOCATING && renderLocating()}
          {appState === AppState.ANALYZING && renderAnalyzing()}
          {appState === AppState.PARKED && renderParked()}
          {appState === AppState.ERROR && (
             <div className="text-center py-10">
               <p className="text-gray-500 mb-4">Something went wrong.</p>
               <Button onClick={() => setAppState(AppState.IDLE)}>Try Again</Button>
             </div>
          )}
        </main>
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AiAnalysisResult } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export const analyzeParkingPhoto = async (base64Image: string): Promise<AiAnalysisResult> => {
  try {
    // We strip the data url prefix if present to get raw base64
    const base64Data = base64Image.replace(/^data:image\/(png|jpeg|jpg|webp);base64,/, "");

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          {
            inlineData: {
              mimeType: 'image/jpeg',
              data: base64Data
            }
          },
          {
            text: "分析这张停车照片。识别楼层（例如 B1, Level 2）、停车位号码，并提供周围环境的简短视觉描述（地标、颜色、柱子），以便稍后找到车子。请用中文（简体）回答。"
          }
        ]
      },
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            floor: { type: Type.STRING, description: "The floor level if visible, otherwise null" },
            spotNumber: { type: Type.STRING, description: "The parking spot number if visible, otherwise null" },
            description: { type: Type.STRING, description: "A short, helpful visual description of where the car is parked in Chinese" }
          }
        }
      }
    });

    const text = response.text;
    if (!text) {
      throw new Error("No response from Gemini");
    }

    return JSON.parse(text) as AiAnalysisResult;
  } catch (error) {
    console.error("Gemini analysis failed:", error);
    // Return empty result on failure to not block the user flow
    return {
      floor: null,
      spotNumber: null,
      description: null
    };
  }
};

